<script setup lang="ts">import{inject,watch}from'vue';import type{ModuleClient}from'../bridge/clients/ModuleClient';import{useAppStore}from'../app/store';import{useModuleStore,type ModuleFilter}from'../app/moduleStore';import{useToastStore}from'../app/toastStore';import QPage from'../design-system/components/QPage.vue';import QPageHeader from'../design-system/components/QPageHeader.vue';import QButton from'../design-system/components/QButton.vue';import QBadge from'../design-system/components/QBadge.vue';import QCard from'../design-system/components/QCard.vue';import QEmptyState from'../design-system/components/QEmptyState.vue';import QSkeleton from'../design-system/components/QSkeleton.vue';import QDrawer from'../design-system/components/QDrawer.vue';const client=inject<ModuleClient>('moduleClient')!;const app=useAppStore();const store=useModuleStore();const toast=useToastStore();async function refresh(showToast=false){store.begin();try{store.complete(await client.getSnapshot());if(showToast)toast.show('Module snapshot refreshed.','success')}catch(e){store.fail(e);toast.show('The host could not refresh modules.','error')}}watch(()=>app.bridge,bridge=>{if(bridge==='Connected'&&store.status==='idle')void refresh()},{immediate:true});const filters:{key:ModuleFilter;label:string}[]=[{key:'all',label:'All'},{key:'running',label:'Running'},{key:'notLoaded',label:'Not loaded'},{key:'issues',label:'Issues'},{key:'invalid',label:'Invalid'}];const tone=(module:{isValid:boolean;runtimeState:string})=>!module.isValid?'danger':module.runtimeState==='Running'?'success':module.runtimeState==='NotLoaded'?'neutral':'info'</script>
<template><QPage><QPageHeader title="Modules" description="Browse the authoritative module state reported by QingToolbox."><QButton @click="refresh(true)" :disabled="store.status==='loading'">{{store.status==='loading'?'Refreshing…':'Refresh'}}</QButton></QPageHeader><section class="module-toolbar"><label><span class="sr-only">Search modules</span><input v-model="store.searchQuery" type="search" placeholder="Search name, author, or ID…"></label><div class="filters" aria-label="Module state filter"><button v-for="filter in filters" :key="filter.key" :class="{active:store.stateFilter===filter.key}" @click="store.stateFilter=filter.key">{{filter.label}}</button></div><span class="module-count">{{store.visibleModules.length}} of {{store.modules.length}}</span></section><div v-if="store.status==='loading'&&store.modules.length===0" class="module-grid"><QSkeleton v-for="n in 4" :key="n"/></div><QEmptyState v-else-if="store.status==='error'" title="Modules are unavailable" :description="store.error"><QButton @click="refresh()">Try again</QButton></QEmptyState><QEmptyState v-else-if="store.visibleModules.length===0" title="No modules found" description="Try another search or state filter."/><section v-else class="module-grid"><QCard v-for="module in store.visibleModules" :key="module.id" class="module-card" tabindex="0" role="button" @click="store.selectedModuleId=module.id" @keydown.enter="store.selectedModuleId=module.id"><div class="module-card-head"><div class="module-icon">{{module.displayName.slice(0,1).toUpperCase()}}</div><div><h2>{{module.displayName}}</h2><span>v{{module.version}} · {{module.author}}</span></div><QBadge :tone="tone(module)">{{module.isValid?module.runtimeState:'Invalid'}}</QBadge></div><p>{{module.displayDescription}}</p><footer><span>{{module.runtimeType}}</span><span v-if="module.errorCount" class="issue">{{module.errorCount}} issue{{module.errorCount===1?'':'s'}}</span></footer></QCard></section><QDrawer :open="!!store.selectedModule" :title="store.selectedModule?.displayName??'Module details'" @close="store.selectedModuleId=null"><template v-if="store.selectedModule"><p class="drawer-description">{{store.selectedModule.displayDescription}}</p><dl class="details"><div><dt>ID</dt><dd>{{store.selectedModule.id}}</dd></div><div><dt>Version</dt><dd>{{store.selectedModule.version}}</dd></div><div><dt>Author</dt><dd>{{store.selectedModule.author}}</dd></div><div><dt>Runtime</dt><dd>{{store.selectedModule.runtimeType}}</dd></div><div><dt>Load mode</dt><dd>{{store.selectedModule.loadMode}}</dd></div><div><dt>State</dt><dd>{{store.selectedModule.runtimeState}}</dd></div><div><dt>Valid</dt><dd>{{store.selectedModule.isValid?'Yes':'No'}}</dd></div><div><dt>Minimum host</dt><dd>{{store.selectedModule.minimumHostVersion}}</dd></div><div><dt>User installed</dt><dd>{{store.selectedModule.isUserInstalled?'Yes':'No'}}</dd></div></dl><h3>Permissions</h3><p>{{store.selectedModule.permissions.length?store.selectedModule.permissions.join(', '):'None declared'}}</p><template v-if="store.selectedModule.errors.length"><h3>Issues</h3><ul><li v-for="error in store.selectedModule.errors" :key="error">{{error}}</li></ul></template></template></QDrawer></QPage></template>
